def u(v, n):
    v = int(v)
    assert 0 <= v < (1 << n), (v, n)
    return v
def s(v, n):
    v = int(v)
    assert -(1 << (n - 1)) <= v < (1 << (n - 1)), (v, n)
    return v & ((1 << n) - 1)

