def rom16(name, vals):
    lines = ['    type t_%s is array(0 to 255) of std_logic_vector(15 downto 0);' % name.lower(),
             '    constant %s : t_%s := (' % (name, name.lower())]
    body = ', '.join('x"%04X"' % v for v in vals)
    out, cur = [], '        '
    for tok in body.split(', '):
        if len(cur) + len(tok) > 110:
            out.append(cur.rstrip()); cur = '        '
        cur += tok + ', '
    out.append(cur.rstrip(', '))
    return '\n'.join(lines + out + ['    );'])

